"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["65826"],{96537(e,t,a){a.r(t),a.d(t,{metadata:()=>n,default:()=>d,frontMatter:()=>s,contentTitle:()=>r,toc:()=>c,assets:()=>l});var n=JSON.parse('{"id":"qiangguo/adamnword","title":"","description":"This is a saying that sounds like it makes a lot of sense, but let\'s examine what it actually amounts to.","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/qiangguo/adamnword.md","sourceDirName":"qiangguo","slug":"/qiangguo/adamnword","permalink":"/en/qiangguo/adamnword","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"adamnword","title":"","hide_table_of_contents":true,"sidebar_label":"A muddled saying: \\"regardless of white cat or black cat, the one that catches mice is a good cat\\""},"sidebar":"qiangguoSidebar","previous":{"title":"\u53F0\u6E7E\u4E0E\u671D\u9C9C\uFF0C\u6700\u7EC8\u4E00\u4E2A\u90FD\u4E0D\u4F1A\u4E5F\u4E0D\u80FD\u5C11\u3002","permalink":"/en/qiangguo/taiwanandkorean"},"next":{"title":"Analysis of \\"regardless of white cat or black cat, the one that catches mice is a good cat\\"","permalink":"/en/qiangguo/goodcat"}}'),o=a(74848),i=a(28453);let s={id:"adamnword",title:"",hide_table_of_contents:!0,sidebar_label:'A muddled saying: "regardless of white cat or black cat, the one that catches mice is a good cat"'},r="A Muddled Saying: \"It Doesn't Matter If a Cat Is Black or White, as Long as It Catches Mice It's a Good Cat\"",l={},c=[];function h(e){let t={h1:"h1",header:"header",p:"p",...(0,i.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.header,{children:(0,o.jsx)(t.h1,{id:"a-muddled-saying-it-doesnt-matter-if-a-cat-is-black-or-white-as-long-as-it-catches-mice-its-a-good-cat",children:"A Muddled Saying: \"It Doesn't Matter If a Cat Is Black or White, as Long as It Catches Mice It's a Good Cat\""})}),"\n",(0,o.jsx)(t.p,{children:"This is a saying that sounds like it makes a lot of sense, but let's examine what it actually amounts to."}),"\n",(0,o.jsx)(t.p,{children:"First, as long as a cat isn't missing limbs, isn't fattened beyond use, or isn't a Persian cat, regardless of black or white\u2014even a calico\u2014catching a mouse or two is nothing worth talking about. The key question is: in reality, when there are two cats, one black and one white, and you can only choose one, and neither happens to be missing limbs, overfed, or Persian, you can't have your cake and eat it too. With only one choice, is it black or white? In this situation, the refusal to debate actually becomes the premise for debate. Those who prefer white will say the black one only caught small mice before, was cruel, not environmentally friendly, lacked sustainable development potential, and so on. Those who prefer black will say the white one tossed the mice aside after catching them, then sneaked off to steal fish, even flirted with the neighbor's cat\u2014eating at home while serving another master, and so on. The real-world bickering will inevitably be endless."}),"\n",(0,o.jsx)(t.p,{children:"Second, once catching mice is made the sole criterion for a good cat, endless tricks will be invented around this single standard. What are these tricks? Both black and white cats know perfectly well."}),"\n",(0,o.jsx)(t.p,{children:"Third, if you already have one at home\u2014say a black cat\u2014but people always think the neighbor's food smells better. Especially after staring at the black cat for so long, a first glimpse of the neighbor's white cat naturally feels fresh and exciting. And if the neighbor is an incredible braggart, claiming his cat catches over a thousand mice a day, even insinuating that your black cat's catches were actually snatched from his mouse pile\u2014what do you do? Option 1: Out-bullshit him. Option 2: Clone his cat. Option 3: Go home, grab some lime, and paint the black cat white. Option 4: ---------"}),"\n",(0,o.jsx)(t.p,{children:"Fourth, some cats are prodigies\u2014before they're even as big as a mouse, they can chase mice all over the streets. But once you actually bring one home and raise it properly, it stops working."}),"\n",(0,o.jsx)(t.p,{children:"Fifth, some cats only perform in their own turf. Forget regular mice\u2014field mice, squirrels, anything even remotely related to mice, none are spared. But the moment they leave their turf, they stop working."}),"\n",(0,o.jsx)(t.p,{children:"Sixth, some cats' relationship with mice even depends on the weather. When the moon is full, they go savage on mice. When the moon droops, their attitude toward mice droops too."}),"\n",(0,o.jsx)(t.p,{children:"Seventh\u2014well, I won't go on."}),"\n",(0,o.jsx)(t.p,{children:"In short, whether catching mice necessarily corresponds to being a good cat regardless of black or white\u2014this question is absolutely not as simple as it sounds. And whether the time has come when we must distinguish black from white is probably also a question that can no longer be avoided."})]})}function d(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(h,{...e})}):h(e)}},28453(e,t,a){a.d(t,{R:()=>s,x:()=>r});var n=a(96540);let o={},i=n.createContext(o);function s(e){let t=n.useContext(i);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:s(e.components),n.createElement(i.Provider,{value:t},e.children)}}}]);